insert into public.academy_lessons (id, course_id, module_id, slug, title, summary, body_md, takeaways, checklist, trade_notes, app_action, quiz, access, status, estimated_minutes, sort_order) values
  (md5('academy:lesson:contractor-sales-academy:finding-qualified-leads')::uuid, md5('academy:course:contractor-sales-academy')::uuid, md5('academy:module:contractor-sales-academy:1. Getting the right leads')::uuid, 'finding-qualified-leads', 'Finding qualified leads', 'Why the best leads are the ones that fit your work, and how to build two or three dependable sources.', 'A lead is only worth chasing if it fits your business: the right type of work, in your service area, with a realistic budget and timeline. Ten of those beat fifty random enquiries, because every appointment costs you drive time, an evening and an estimate.
